def match(orders):
    trades = []
    buy_book = []  # [(price, arrival_time, id, qty)]
    sell_book = []  # [(price, arrival_time, id, qty)]
    order_map = {}  # id -> (side, price, qty, arrival_time, index_in_book)
    arrival_counter = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, qty, arrival_time, book_index = order_map[order_id]
                if side == 'buy':
                    if book_index < len(buy_book) and buy_book[book_index][2] == order_id:
                        buy_book.pop(book_index)
                        # Update indices for all orders after this one
                        for i in range(book_index, len(buy_book)):
                            oid = buy_book[i][2]
                            if oid in order_map:
                                s, p, q, a, _ = order_map[oid]
                                order_map[oid] = (s, p, q, a, i)
                else:  # side == 'sell'
                    if book_index < len(sell_book) and sell_book[book_index][2] == order_id:
                        sell_book.pop(book_index)
                        # Update indices for all orders after this one
                        for i in range(book_index, len(sell_book)):
                            oid = sell_book[i][2]
                            if oid in order_map:
                                s, p, q, a, _ = order_map[oid]
                                order_map[oid] = (s, p, q, a, i)
                del order_map[order_id]
        else:
            order_id = order[1]
            side = order[2]
            qty = order[4] if order[0] != 'market' else order[3]
            price = order[3] if order[0] in ['limit', 'ioc'] else None

            if side == 'buy':
                # Match against sell_book
                while qty > 0 and sell_book:
                    sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]
                    if price is not None and sell_price > price:
                        break

                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, trade_qty])

                    qty -= trade_qty
                    sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)

                    if sell_book[0][3] == 0:
                        sell_book.pop(0)
                        if sell_id in order_map:
                            del order_map[sell_id]
                        # Update indices
                        for i in range(len(sell_book)):
                            oid = sell_book[i][2]
                            if oid in order_map:
                                s, p, q, a, _ = order_map[oid]
                                order_map[oid] = (s, p, q, a, i)
                    else:
                        # Update order_map with new qty
                        if sell_id in order_map:
                            s, p, q, a, idx = order_map[sell_id]
                            order_map[sell_id] = (s, p, sell_book[0][3], a, idx)

                # Add remaining to buy_book
                if qty > 0 and order[0] == 'limit':
                    buy_book.append((price, arrival_counter, order_id, qty))
                    order_map[order_id] = ('buy', price, qty, arrival_counter, len(buy_book) - 1)
                    arrival_counter += 1
                    # Re-sort buy_book by price (descending) then arrival time
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    # Update order_map indices
                    for i in range(len(buy_book)):
                        oid = buy_book[i][2]
                        if oid in order_map:
                            s, p, q, a, _ = order_map[oid]
                            order_map[oid] = (s, p, q, a, i)

            else:  # side == 'sell'
                # Match against buy_book
                while qty > 0 and buy_book:
                    buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]
                    if price is not None and buy_price < price:
                        break

                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, buy_price, trade_qty])

                    qty -= trade_qty
