                    if buy_book[0][3] == 0:
                        buy_book.pop(0)
                        if buy_id in order_map:
                            del order_map[buy_id]
                        # Update indices
                        for i in range(len(buy_book)):
                            oid = buy_book[i][2]
                            if oid in order_map:
                                s, p, q, a, _ = order_map[oid]
                                order_map[oid] = (s, p, q, a, i)
                    else:
                        # Update order_map with new qty
                        if buy_id in order_map:
                            s, p, q, a, idx = order_map[buy_id]
                            order_map[buy_id] = (s, p, buy_book[0][3], a, idx)

                # Add remaining to sell_book
                if qty > 0 and order[0] == 'limit':
                    sell_book.append((price, arrival_counter, order_id, qty))
                    order_map[order_id] = ('sell', price, qty, arrival_counter, len(sell_book) - 1)
                    arrival_counter += 1
                    # Re-sort sell_book by price (ascending) then arrival time
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    # Update order_map indices
                    for i in range(len(sell_book)):
                        oid = sell_book[i][2]
                        if oid in order_map:
                            s, p, q, a, _ = order_map[oid]
                            order_map[oid] = (s, p, q, a, i)

    return trades

